import { useState } from 'react';
import { motion } from 'framer-motion';
import { Vault, CircleDollarSign, ArrowLeft } from 'lucide-react';
import CurrencySection from './CurrencySection';
import CryptoSection from './CryptoSection';

const glassCardStyle: React.CSSProperties = {
  background: 'var(--tg-theme-secondary-bg-color)',
  borderRadius: '24px',
  border: '1px solid rgba(255, 117, 25, 0.25)',
  boxShadow: '0 8px 32px rgba(0, 0, 0, 0.2)',
  padding: '20px',
  cursor: 'pointer',
};

const iconContainerStyle: React.CSSProperties = {
  width: '56px',
  height: '56px',
  borderRadius: '16px',
  background: 'linear-gradient(135deg, rgba(255, 117, 25, 0.15), rgba(255, 117, 25, 0.05))',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  marginRight: '16px',
};

export default function CartView() {
  const [activeView, setActiveView] = useState<'menu' | 'documents' | 'currency'>('menu');

  const backButton = (
    <button
      onClick={() => setActiveView('menu')}
      className="flex items-center gap-2 text-[var(--tg-theme-hint-color)] hover:text-[var(--tg-theme-text-color)] mb-4 transition-colors"
    >
      <ArrowLeft size={18} />
      <span>Назад</span>
    </button>
  );

  return (
    <div className="px-4 pt-4 pb-24">
      {activeView === 'menu' && (
        <div className="flex flex-col gap-4">
          {/* Карточка Документы */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.2 }}
            style={glassCardStyle}
            onClick={() => setActiveView('documents')}
          >
            <div className="flex items-center">
              <div style={iconContainerStyle}>
                <Vault size={28} color="var(--tg-theme-link-color)" />
              </div>
              <div>
                <h3 className="text-lg font-semibold text-[var(--tg-theme-text-color)]">
                  Документы
                </h3>
                <p className="text-sm text-[var(--tg-theme-hint-color)]">
                  Закрытый раздел для участников клуба
                </p>
              </div>
            </div>
          </motion.div>

          {/* Карточка Валютный калькулятор */}
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.25 }}
            style={glassCardStyle}
            onClick={() => setActiveView('currency')}
          >
            <div className="flex items-center">
              <div style={iconContainerStyle}>
                <CircleDollarSign size={28} color="var(--tg-theme-link-color)" />
              </div>
              <div>
                <h3 className="text-lg font-semibold text-[var(--tg-theme-text-color)]">
                  Валютный калькулятор
                </h3>
                <p className="text-sm text-[var(--tg-theme-hint-color)]">
                  Курсы фиатных и криптовалют для расчётов
                </p>
              </div>
            </div>
          </motion.div>
        </div>
      )}

      {activeView === 'documents' && (
        <div>
          {backButton}
          <div className="flex flex-col items-center justify-center" style={{ minHeight: '50vh' }}>
            <div style={{ ...glassCardStyle, cursor: 'default' }} className="text-center">
              <Vault size={64} color="var(--tg-theme-link-color)" style={{ marginBottom: '16px' }} />
              <h3 className="text-xl font-semibold text-[var(--tg-theme-text-color)] mb-2">
                Закрытый раздел
              </h3>
              <p className="text-sm text-[var(--tg-theme-hint-color)]">
                Доступ только для участников клуба
              </p>
            </div>
          </div>
        </div>
      )}

      {activeView === 'currency' && (
        <div>
          {backButton}
          <CurrencySection />
          <CryptoSection />
        </div>
      )}
    </div>
  );
}
