import { useState, FormEvent } from 'react';
import { motion } from 'framer-motion';
import { X } from 'lucide-react';

interface Props {
  onClose: () => void;
  onSubmit: () => void;
}

export default function OrderForm({ onClose, onSubmit }: Props) {
  const [name, setName] = useState('');
  const [contact, setContact] = useState('');
  const [comment, setComment] = useState('');
  const [agreed, setAgreed] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  const validate = () => {
    const e: Record<string, string> = {};
    if (!name.trim()) e.name = 'Обязательное поле';
    if (!contact.trim()) e.contact = 'Введите Telegram или email';
    if (!agreed) e.agreed = 'Необходимо согласие';
    setErrors(e);
    return Object.keys(e).length === 0;
  };

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (validate()) onSubmit();
  };

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 z-[200] bg-black/70 flex items-center justify-center p-4"
      onClick={onClose}
    >
      <motion.form
        initial={{ scale: 0.9 }}
        animate={{ scale: 1 }}
        exit={{ scale: 0.9 }}
        onClick={(e) => e.stopPropagation()}
        className="bg-card rounded-2xl p-6 w-full max-w-md border border-white/10"
        onSubmit={handleSubmit}
      >
        <div className="flex justify-between items-center mb-4">
          <h3 className="text-xl font-bold text-white">Оставить заявку</h3>
          <button type="button" onClick={onClose} className="text-white/50">
            <X size={24} />
          </button>
        </div>

        <div className="space-y-4">
          <input
            type="text"
            placeholder="Имя *"
            value={name}
            onChange={(e) => setName(e.target.value)}
            className="w-full p-3 rounded-xl bg-white/5 border border-white/10 text-white placeholder-white/30 focus:border-gold focus:outline-none"
          />
          {errors.name && <p className="text-red-400 text-sm">{errors.name}</p>}

          <input
            type="text"
            placeholder="Telegram / Email *"
            value={contact}
            onChange={(e) => setContact(e.target.value)}
            className="w-full p-3 rounded-xl bg-white/5 border border-white/10 text-white placeholder-white/30 focus:border-gold focus:outline-none"
          />
          {errors.contact && <p className="text-red-400 text-sm">{errors.contact}</p>}

          <textarea
            placeholder="Комментарий (необязательно)"
            value={comment}
            onChange={(e) => setComment(e.target.value)}
            rows={3}
            className="w-full p-3 rounded-xl bg-white/5 border border-white/10 text-white placeholder-white/30 focus:border-gold focus:outline-none resize-none"
          />

          <label className="flex items-start gap-2 text-white/70 text-sm">
            <input
              type="checkbox"
              checked={agreed}
              onChange={(e) => setAgreed(e.target.checked)}
              className="mt-1 accent-gold"
            />
            <span>Я согласен с условиями конфиденциальности и обработки персональных данных</span>
          </label>
          {errors.agreed && <p className="text-red-400 text-sm">{errors.agreed}</p>}
        </div>

        <button
          type="submit"
          className="w-full bg-gold hover:bg-gold-light text-dark font-semibold py-3 rounded-xl mt-6 transition-colors active:scale-95"
        >
          Отправить заявку
        </button>
      </motion.form>
    </motion.div>
  );
}
