import { useState } from 'react';
import { Select, Button } from '@telegram-apps/telegram-ui';
import { Ship, ArrowUpFromDot, ArrowDownToDot } from 'lucide-react';
import containerShip from '../assets/container-ship.jpg';
import logo from '../assets/logo.png';

const LINES = ['Maersk', 'MSC', 'CMA CGM', 'Hapag-Lloyd', 'ONE'];
const POLS = ['Роттердам', 'Гданьск', 'Гамбург', 'Антверпен'];
const PODS = [
  'Стамбул', 'Мерсин', 'Измир',
  'Дубай', 'Абу-Даби', 'Шарджа',
  'Доха', 'Пирей', 'Салоники',
  'Гдыня', 'Гданьск', 'Баку',
  'Поти', 'Батуми', 'Новороссийск',
  'Другой (ввести вручную)'
];

const CONTAINER_TYPES = ['20ft', '40ft'];

// Справочник маршрутных ставок (20ft / 40ft) — реальные данные на май 2026
const RATES_BOOK: Record<string, { rate20ft: number; rate40ft: number }> = {
  // --- Турция ---
  'Maersk|Роттердам|Стамбул': { rate20ft: 2375, rate40ft: 3600 },
  'Maersk|Гданьск|Стамбул': { rate20ft: 2440, rate40ft: 3700 },
  'Maersk|Антверпен|Мерсин': { rate20ft: 2450, rate40ft: 3750 },
  'MSC|Роттердам|Стамбул': { rate20ft: 3400, rate40ft: 4600 },
  'MSC|Антверпен|Мерсин': { rate20ft: 3400, rate40ft: 4600 },
  'CMA CGM|Гданьск|Стамбул': { rate20ft: 3500, rate40ft: 5000 },

  // --- ОАЭ ---
  'Maersk|Гамбург|Дубай': { rate20ft: 3200, rate40ft: 4800 },
  'MSC|Гамбург|Дубай': { rate20ft: 3600, rate40ft: 5200 },
  'CMA CGM|Роттердам|Дубай': { rate20ft: 3300, rate40ft: 4600 },
  'ONE|Гамбург|Дубай': { rate20ft: 3200, rate40ft: 4600 },
  'Hapag-Lloyd|Роттердам|Абу-Даби': { rate20ft: 3950, rate40ft: 5600 },

  // --- Катар ---
  'Hapag-Lloyd|Гамбург|Доха': { rate20ft: 3950, rate40ft: 5600 },

  // --- Грузия ---
  'CMA CGM|Роттердам|Поти': { rate20ft: 3700, rate40ft: 5200 },
  'CMA CGM|Гамбург|Поти': { rate20ft: 3750, rate40ft: 5300 },
  'MSC|Роттердам|Поти': { rate20ft: 3400, rate40ft: 4700 },
  'MSC|Гамбург|Поти': { rate20ft: 3450, rate40ft: 4800 },
  'Hapag-Lloyd|Роттердам|Поти': { rate20ft: 3950, rate40ft: 5600 },
  'Hapag-Lloyd|Гамбург|Поти': { rate20ft: 4000, rate40ft: 5700 },

  // --- Азербайджан (мультимодальные ставки) ---
  'CMA CGM|Роттердам|Баку': { rate20ft: 4200, rate40ft: 5800 },
  'MSC|Роттердам|Баку': { rate20ft: 3900, rate40ft: 5300 },
  'MSC|Гамбург|Баку': { rate20ft: 3950, rate40ft: 5400 },
  'Hapag-Lloyd|Роттердам|Баку': { rate20ft: 4450, rate40ft: 6200 },

  // --- Россия (с оговорками) ---
  'MSC|Роттердам|Новороссийск': { rate20ft: 4100, rate40ft: 5700 },
  'MSC|Гамбург|Новороссийск': { rate20ft: 4150, rate40ft: 5800 },
};

const FAQ_DATA = [
  { q: 'Что такое демерредж?', a: 'Плата за сверхнормативное использование контейнера в порту после истечения бесплатного периода.' },
  { q: 'Что такое детеншен?', a: 'Плата за задержку контейнера вне порта после вывоза.' },
  { q: 'Как рассчитывается ставка?', a: 'Ставка зависит от линии, портов и текущей рыночной ситуации. Указанные значения — справочные.' },
];

const glassCardStyle: React.CSSProperties = {
  background: 'var(--tg-theme-secondary-bg-color)',
  borderRadius: '24px',
  border: '1px solid rgba(255, 117, 25, 0.25)',
  boxShadow: '0 8px 32px rgba(0, 0, 0, 0.2)',
  padding: '16px',
};

const selectWrapperStyle: React.CSSProperties = {
  display: 'flex',
  alignItems: 'center',
  gap: '12px',
};

const iconStyle: React.CSSProperties = {
  color: 'var(--tg-theme-link-color)',
  flexShrink: 0,
};

const textStyle: React.CSSProperties = { color: 'var(--tg-theme-text-color)', fontSize: '15px' };
const subtitleStyle: React.CSSProperties = { color: 'var(--tg-theme-hint-color)', fontSize: '13px', marginBottom: '4px' };

export default function DemurrageCalculator() {
  const [line, setLine] = useState(LINES[0]);
  const [pol, setPol] = useState(POLS[0]);
  const [pod, setPod] = useState(PODS[0]);
  const [customPod, setCustomPod] = useState('');
  const [containerType, setContainerType] = useState(CONTAINER_TYPES[0]);
  const [result, setResult] = useState<{ rate: number; source: string } | null>(null);
  const [loading, setLoading] = useState(false);
  const [faqOpen, setFaqOpen] = useState<number | null>(null);

  const handleCalculate = () => {
    setLoading(true);
    const finalPod = pod === 'Другой (ввести вручную)' ? customPod.trim() : pod;
    if (!finalPod) {
      setLoading(false);
      return;
    }
    const key = `${line}|${pol}|${finalPod}`;
    const rateObj = RATES_BOOK[key];

    setTimeout(() => {
      if (rateObj) {
        const rate = containerType === '20ft' ? rateObj.rate20ft : rateObj.rate40ft;
        setResult({ rate, source: 'reference' });
      } else {
        // Проверка для РФ: если выбран Новороссийск, но линия не MSC
        if (finalPod === 'Новороссийск' && line !== 'MSC') {
          setResult(null);
          alert('Для данного направления доступны только ставки MSC. Другие линии приостановили сервис.');
        } else {
          setResult(null);
        }
      }
      setLoading(false);
    }, 300);
  };

  return (
    <div className="px-4 pt-4 pb-24 flex flex-col gap-6">
      {/* Заголовок с логотипом */}
      <div className="flex flex-col items-center gap-3 pt-2">
        <div
          style={{
            width: '100%',
            maxWidth: '200px',
            borderRadius: '20px',
            overflow: 'hidden',
            border: '1px solid rgba(255, 117, 25, 0.25)',
            background: 'var(--tg-theme-secondary-bg-color)',
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center',
          }}
        >
          <img
            src={logo}
            alt="ATOMICA"
            style={{
              width: '100%',
              height: 'auto',
              objectFit: 'contain',
              display: 'block',
            }}
          />
        </div>
        <h2 className="text-2xl font-bold text-[var(--tg-theme-text-color)]">Расчёт фрахта</h2>
        <p className="text-center text-[var(--tg-theme-hint-color)] text-sm">
          Демерредж и детеншн для вашего маршрута
        </p>
      </div>

      {/* Калькулятор */}
      <div style={glassCardStyle}>
        <div className="flex flex-col gap-5">
          <div>
            <span style={subtitleStyle}>Судоходная линия</span>
            <div style={selectWrapperStyle}>
              <Ship size={20} style={iconStyle} />
              <Select value={line} onChange={(e) => setLine(e.target.value)} style={textStyle}>
                {LINES.map(l => <option key={l} value={l}>{l}</option>)}
              </Select>
            </div>
          </div>

          <div>
            <span style={subtitleStyle}>Порт отправления</span>
            <div style={selectWrapperStyle}>
              <ArrowUpFromDot size={20} style={iconStyle} />
              <Select value={pol} onChange={(e) => setPol(e.target.value)} style={textStyle}>
                {POLS.map(p => <option key={p} value={p}>{p}</option>)}
              </Select>
            </div>
          </div>

          <div>
            <span style={subtitleStyle}>Порт назначения</span>
            <div style={selectWrapperStyle}>
              <ArrowDownToDot size={20} style={iconStyle} />
              <Select value={pod} onChange={(e) => setPod(e.target.value)} style={textStyle}>
                {PODS.map(p => <option key={p} value={p}>{p}</option>)}
              </Select>
            </div>
            {pod === 'Другой (ввести вручную)' && (
              <input
                type="text"
                value={customPod}
                onChange={(e) => setCustomPod(e.target.value)}
                placeholder="Введите название порта"
                style={{
                  width: '100%',
                  marginTop: '8px',
                  padding: '10px',
                  borderRadius: '10px',
                  border: '1px solid rgba(255,255,255,0.1)',
                  background: 'rgba(255,255,255,0.05)',
                  color: 'var(--tg-theme-text-color)',
                  fontSize: '14px',
                }}
              />
            )}
          </div>

          <div>
            <span style={subtitleStyle}>Тип контейнера</span>
            <div style={selectWrapperStyle}>
              <Ship size={20} style={iconStyle} />
              <Select value={containerType} onChange={(e) => setContainerType(e.target.value)} style={textStyle}>
                {CONTAINER_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
              </Select>
            </div>
          </div>

          <Button
            onClick={handleCalculate}
            loading={loading}
            style={{
              background: 'linear-gradient(135deg, var(--tg-theme-link-color), #e55a00)',
              color: 'white',
              fontWeight: 'bold',
              padding: '14px',
              borderRadius: '14px',
              fontSize: '16px',
              boxShadow: '0 4px 15px rgba(255, 117, 25, 0.3)',
            }}
          >
            Рассчитать стоимость
          </Button>

          {/* Результат расчёта */}
          {result && (
            <div style={{
              background: 'rgba(255, 117, 25, 0.1)',
              borderRadius: '14px',
              padding: '16px',
              textAlign: 'center',
            }}>
              <p style={{ color: 'var(--tg-theme-hint-color)', fontSize: '13px' }}>Справочная ставка</p>
              <p style={{ color: 'var(--tg-theme-link-color)', fontSize: '28px', fontWeight: 'bold' }}>
                ${result.rate}/маршрут ({containerType})
              </p>
              <p style={{ color: 'var(--tg-theme-hint-color)', fontSize: '11px', marginTop: '4px' }}>
                Для точной ставки свяжитесь с менеджером
              </p>
            </div>
          )}
        </div>
      </div>

      {/* Таблица рыночных ставок */}
      <div style={glassCardStyle}>
        <h3 className="text-lg font-semibold text-[var(--tg-theme-text-color)] mb-4">
          Ориентировочные ставки
        </h3>
        <div className="overflow-x-auto">
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ borderBottom: '1px solid rgba(255,255,255,0.1)' }}>
                <th style={{ padding: '8px', textAlign: 'left', color: 'var(--tg-theme-hint-color)', fontSize: '12px' }}>Направление</th>
                <th style={{ padding: '8px', textAlign: 'right', color: 'var(--tg-theme-hint-color)', fontSize: '12px' }}>20ft</th>
                <th style={{ padding: '8px', textAlign: 'right', color: 'var(--tg-theme-hint-color)', fontSize: '12px' }}>40ft</th>
              </tr>
            </thead>
            <tbody>
              {Object.entries(RATES_BOOK).slice(0, 7).map(([key, rates]) => {
                const [l, p1, p2] = key.split('|');
                return (
                  <tr key={key} style={{ borderBottom: '1px solid rgba(255,255,255,0.05)' }}>
                    <td style={{ padding: '8px', color: 'var(--tg-theme-text-color)', fontSize: '13px' }}>{l} → {p1} → {p2}</td>
                    <td style={{ padding: '8px', textAlign: 'right', color: 'var(--tg-theme-link-color)', fontSize: '14px', fontWeight: 'bold' }}>${rates.rate20ft}</td>
                    <td style={{ padding: '8px', textAlign: 'right', color: 'var(--tg-theme-link-color)', fontSize: '14px', fontWeight: 'bold' }}>${rates.rate40ft}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
        <p style={{ color: 'var(--tg-theme-hint-color)', fontSize: '11px', marginTop: '8px' }}>
          * Для Новороссийска доступны только ставки MSC. Полные данные — в калькуляторе.
        </p>
      </div>

      {/* FAQ с фото контейнеровоза и аккордеоном */}
      <div style={{ position: 'relative', borderRadius: '24px', overflow: 'hidden', marginTop: '24px' }}>
        <img
          src={containerShip}
          alt="Контейнеровоз"
          style={{
            width: '100%',
            height: '250px',
            objectFit: 'cover',
            filter: 'brightness(0.7)',
          }}
        />
        <div style={{
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: 'linear-gradient(to top, rgba(0,0,0,0.7), transparent)',
          padding: '24px',
          color: 'white',
          overflowY: 'auto',
        }}>
          <h3 style={{ fontSize: '1.4rem', fontWeight: 'bold', marginBottom: '16px' }}>
            ❓ Часто задаваемые вопросы
          </h3>
          {FAQ_DATA.map((item, i) => (
            <div key={i} style={{ marginBottom: '12px' }}>
              <button
                onClick={() => setFaqOpen(faqOpen === i ? null : i)}
                style={{
                  width: '100%',
                  textAlign: 'left',
                  background: 'rgba(255,255,255,0.1)',
                  border: 'none',
                  borderRadius: '8px',
                  padding: '10px',
                  color: 'white',
                  fontWeight: 600,
                  fontSize: '0.95rem',
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                  cursor: 'pointer',
                }}
              >
                {item.q}
                <span style={{ transform: faqOpen === i ? 'rotate(180deg)' : 'none', transition: '0.2s' }}>▼</span>
              </button>
              {faqOpen === i && (
                <div style={{
                  padding: '10px',
                  fontSize: '0.85rem',
                  opacity: 0.9,
                }}>
                  {item.a}
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* Преимущества в колонку */}
      <div className="flex flex-col gap-3">
        {[
          { icon: '🚢', title: 'Прямой фрахт', desc: 'Atomica имеет собственных агентов и прямые контракты с линиями. Это исключает наценки посредников и обеспечивает уникальные ставки.' },
          { icon: '⚓️', title: 'Порты Европы', desc: 'Порты отправления фиксированы расположением складов Atomica. Мы не занимаемся экспедированием и гарантируем стабильность цепочки.' },
          { icon: '💎', title: 'Точные ставки', desc: 'Данные поступают напрямую от ShippingRates.org. Финальные условия фиксируются при согласовании драфта с партнёрами.' },
          { icon: '🛡️', title: 'Страхование', desc: 'Atomica предлагает несколько моделей покрытия. Оптимальная схема обсуждается индивидуально при оформлении сделки.' },
        ].map((item, i) => (
          <div key={i} style={glassCardStyle}>
            <span style={{ fontSize: '28px' }}>{item.icon}</span>
            <h5 style={{ fontWeight: '600', marginTop: '8px', fontSize: '1rem' }}>{item.title}</h5>
            <p style={{ opacity: 0.8, fontSize: '0.9rem', marginTop: '4px' }}>{item.desc}</p>
          </div>
        ))}
      </div>
    </div>
  );
}
