import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import CategoryTabs from './components/CategoryTabs';
import AssetCard from './components/AssetCard';
import AssetDetail from './components/AssetDetail';
import CartView from './components/CartView';
import { mockAssets } from './data/mockAssets';

type Page = 'catalog' | 'detail' | 'cart';

export default function PremiumApp() {
  const [page, setPage] = useState<Page>('catalog');
  const [selectedAssetId, setSelectedAssetId] = useState<string | null>(null);
  const [category, setCategory] = useState<string>('all');

  const filteredAssets = category === 'all'
    ? mockAssets.filter(a => !a.is_hidden)
    : mockAssets.filter(a => a.category === category && !a.is_hidden);

  const selectedAsset = selectedAssetId
    ? mockAssets.find(a => a.id === selectedAssetId) || null
    : null;

  return (
    <div className="min-h-screen bg-[var(--tg-theme-bg-color)] text-[var(--tg-theme-text-color)]">
      <div className="relative bg-gradient-to-r from-brand to-brand-light px-4 pt-6 pb-8 shadow-lg">
        <h1 className="text-2xl font-bold text-white text-center tracking-wide">
          PREMIUM ASSETS
        </h1>
        <p className="text-center text-white/80 text-xs mt-1">Эксклюзивные возможности</p>
      </div>

      <AnimatePresence mode="wait">
        {page === 'catalog' && (
          <motion.div key="catalog" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="px-4 pt-4">
            <CategoryTabs current={category} onChange={setCategory} />
            <div className="space-y-4 mt-4">
              {filteredAssets.map((asset, i) => (
                <AssetCard
                  key={asset.id}
                  asset={asset}
                  index={i}
                  onSelect={() => { setSelectedAssetId(asset.id); setPage('detail'); }}
                />
              ))}
            </div>
          </motion.div>
        )}
        {page === 'detail' && selectedAsset && (
          <motion.div key="detail" initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }} className="px-4 pt-4">
            <AssetDetail asset={selectedAsset} onBack={() => { setPage('catalog'); setSelectedAssetId(null); }} />
          </motion.div>
        )}
        {page === 'cart' && (
          <motion.div key="cart" initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: -20 }} className="px-4 pt-4">
            <CartView onBack={() => setPage('catalog')} />
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
