import { motion } from 'framer-motion';
import { ChevronRight } from 'lucide-react';
import type { Asset } from '../data/mockAssets';

interface Props {
  asset: Asset;
  index: number;
  onSelect: () => void;
}

export default function AssetCard({ asset, index, onSelect }: Props) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: index * 0.1, duration: 0.4 }}
      onClick={onSelect}
      className="bg-[var(--tg-theme-secondary-bg-color)] rounded-2xl overflow-hidden border border-white/5 active:scale-[0.98] transition-transform cursor-pointer"
    >
      {asset.image_urls[0] && (
        <img
          src={asset.image_urls[0]}
          alt={asset.name}
          className="w-full h-40 object-cover opacity-80"
        />
      )}
      <div className="p-4">
        <div className="flex items-start justify-between">
          <div className="flex-1 min-w-0">
            <h3 className="font-semibold text-[var(--tg-theme-text-color)] truncate">{asset.name}</h3>
            <div className="flex gap-2 mt-1 text-sm text-[var(--tg-theme-hint-color)]">
              <span className="px-2 py-0.5 rounded-full bg-brand/20 text-brand text-xs uppercase tracking-wider">
                {asset.category}
              </span>
              <span>{asset.available_units > 0 ? `${asset.available_units} шт.` : 'Эксклюзив'}</span>
            </div>
            <p className="mt-2 text-brand font-bold text-lg">{asset.price}</p>
          </div>
          <ChevronRight className="text-[var(--tg-theme-hint-color)] mt-1" size={20} />
        </div>
      </div>
    </motion.div>
  );
}
