import { useState } from 'react';
import { motion } from 'framer-motion';
import { LineChart, Line, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';
import { ArrowRight } from 'lucide-react';

const API_KEY = import.meta.env.VITE_EXCHANGE_RATE_API_KEY;
const popularCurrencies = ['USD', 'EUR', 'RUB', 'GBP', 'CNY', 'TRY', 'KZT'];

const glassCardStyle: React.CSSProperties = {
  background: 'var(--tg-theme-secondary-bg-color)',
  borderRadius: '24px',
  border: '1px solid rgba(255, 117, 25, 0.25)',
  boxShadow: '0 8px 32px rgba(0, 0, 0, 0.2)',
  padding: '20px',
};

export default function CurrencySection() {
  const [from, setFrom] = useState('USD');
  const [to, setTo] = useState('RUB');
  const [amountStr, setAmountStr] = useState<string>('1');
  const [rate, setRate] = useState<number | null>(null);
  const [converted, setConverted] = useState<number | null>(null);
  const [date, setDate] = useState('');
  const [history, setHistory] = useState<any[]>([]);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [calculated, setCalculated] = useState(false);

  const amount = parseFloat(amountStr.replace(',', '.')) || 0;

  const loadLatest = async (fromCur: string, toCur: string, amt: number) => {
    setLoading(true);
    setError('');
    setRate(null);
    setConverted(null);
    setCalculated(false);
    try {
      const res = await fetch(`https://v6.exchangerate-api.com/v6/${API_KEY}/latest/${fromCur}`);
      if (!res.ok) throw new Error('API error');
      const data = await res.json();
      if (data.result === 'error') throw new Error(data['error-type']);
      const r = data.conversion_rates?.[toCur];
      if (!r) throw new Error('No rate');
      setRate(r);
      setConverted(amt * r);
      setDate(data.time_last_update_utc?.slice(0, 10) || new Date().toISOString().slice(0, 10));
      setCalculated(true);
    } catch {
      setError('Не удалось получить курс');
      setRate(null);
      setConverted(null);
      setCalculated(false);
    } finally {
      setLoading(false);
    }
  };

  const loadHistory = async (fromCur: string, toCur: string) => {
    const rows = [];
    const today = new Date();
    for (let i = 6; i >= 0; i--) {
      const d = new Date(today);
      d.setDate(today.getDate() - i);
      const iso = d.toISOString().slice(0, 10);
      try {
        const res = await fetch(`https://v6.exchangerate-api.com/v6/${API_KEY}/history/${fromCur}/${iso}`);
        if (res.ok) {
          const data = await res.json();
          if (data.result === 'success' && data.conversion_rates?.[toCur]) {
            rows.push({ date: iso, rate: data.conversion_rates[toCur] });
          }
        }
      } catch {}
    }
    setHistory(rows);
  };

  const handleCalculate = () => {
    loadLatest(from, to, amount);
    loadHistory(from, to);
  };

  const handleFromChange = (value: string) => {
    setFrom(value);
    setCalculated(false);
    setRate(null);
    setConverted(null);
  };
  const handleToChange = (value: string) => {
    setTo(value);
    setCalculated(false);
    setRate(null);
    setConverted(null);
  };
  const handleAmountChange = (value: string) => {
    setAmountStr(value);
    setCalculated(false);
    setRate(null);
    setConverted(null);
  };

  const quickPairs = ['EUR/USD', 'USD/RUB', 'EUR/RUB'];
  const handleQuick = (pair: string) => {
    const [f, t] = pair.split('/');
    setFrom(f);
    setTo(t);
    setAmountStr('1');
    loadLatest(f, t, 1);
    loadHistory(f, t);
  };

  return (
    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }} style={glassCardStyle}>
      <h3 className="text-lg font-semibold text-[var(--tg-theme-text-color)] mb-3">💱 Курс валют</h3>

      <div className="flex gap-2 mb-4">
        <select value={from} onChange={(e) => handleFromChange(e.target.value)} className="w-full p-3 rounded-xl bg-white/5 border border-white/10 text-[var(--tg-theme-text-color)] focus:border-orange-500 focus:outline-none">
          {popularCurrencies.map(c => <option key={c} value={c}>{c}</option>)}
        </select>
        <ArrowRight size={20} className="self-center text-[var(--tg-theme-link-color)]" />
        <select value={to} onChange={(e) => handleToChange(e.target.value)} className="w-full p-3 rounded-xl bg-white/5 border border-white/10 text-[var(--tg-theme-text-color)] focus:border-orange-500 focus:outline-none">
          {popularCurrencies.map(c => <option key={c} value={c}>{c}</option>)}
        </select>
      </div>

      <input
        inputMode="decimal"
        value={amountStr}
        onChange={(e) => handleAmountChange(e.target.value)}
        placeholder="Сумма"
        className="w-full p-3 rounded-xl bg-white/5 border border-white/10 text-[var(--tg-theme-text-color)] placeholder:text-[var(--tg-theme-hint-color)] focus:border-orange-500 focus:outline-none mb-4"
      />

      <button onClick={handleCalculate} className="w-full bg-orange-500 hover:bg-orange-600 text-white font-semibold py-3 rounded-xl transition-colors active:scale-95">
        Рассчитать
      </button>

      {loading && <p className="text-center text-[var(--tg-theme-hint-color)] mt-2">Загрузка...</p>}

      {calculated && rate !== null && (
        <div className="mt-4 p-4 rounded-xl border border-orange-400/40 bg-black/20 text-center">
          <p className="text-[var(--tg-theme-hint-color)] text-sm">Справочный курс</p>
          <p className="text-[var(--tg-theme-text-color)] text-2xl font-bold">1 {from} = <span className="text-orange-500">{rate.toFixed(2)}</span> {to}</p>
          <p className="text-[var(--tg-theme-text-color)] text-lg mt-1">{amount} {from} = <span className="text-orange-500">{converted?.toFixed(2)}</span> {to}</p>
          <p className="text-[var(--tg-theme-hint-color)] text-xs mt-1">на {date}</p>
        </div>
      )}

      {error && <p className="text-red-400 text-center mt-3">{error}</p>}

      {history.length > 0 && calculated && (
        <div style={{ width: '100%', height: 200, marginTop: 20 }}>
          <ResponsiveContainer>
            <LineChart data={history}>
              <XAxis dataKey="date" hide />
              <YAxis domain={['auto', 'auto']} width={30} />
              <Tooltip />
              <Line type="monotone" dataKey="rate" stroke="#FF6B35" strokeWidth={2} dot={false} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      )}

      <div className="flex flex-wrap gap-2 mt-4">
        {quickPairs.map(pair => (
          <button key={pair} onClick={() => handleQuick(pair)} className="px-3 py-1.5 rounded-full bg-white/5 text-[var(--tg-theme-hint-color)] text-xs hover:bg-white/10 transition-colors">
            {pair}
          </button>
        ))}
      </div>
    </motion.div>
  );
}
