import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { RefreshCw, ArrowRight } from 'lucide-react';

const glassCardStyle: React.CSSProperties = {
  background: 'var(--tg-theme-secondary-bg-color)',
  borderRadius: '24px',
  border: '1px solid rgba(255, 117, 25, 0.25)',
  boxShadow: '0 8px 32px rgba(0, 0, 0, 0.2)',
  padding: '20px',
};

const COINS = {
  BTC: 'bitcoin',
  ETH: 'ethereum',
  XMR: 'monero',
  USDT: 'tether',
};

const CURRENCY_NAMES: Record<string, string> = {
  BTC: '₿ Bitcoin',
  ETH: 'Ξ Ethereum',
  XMR: 'ɱ Monero',
  USDT: '₮ USDT',
};

export default function CryptoSection() {
  const [from, setFrom] = useState('BTC');
  const [to, setTo] = useState('USDT');
  const [amount, setAmount] = useState('1');
  const [result, setResult] = useState<number | null>(null);
  const [prices, setPrices] = useState<Record<string, number>>({});
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [lastUpdate, setLastUpdate] = useState('');

  const fetchPrices = async () => {
    setLoading(true);
    setError('');
    try {
      const ids = Object.values(COINS).join(',');
      const url = `https://api.coingecko.com/api/v3/simple/price?ids=${ids}&vs_currencies=usd`;
      const res = await fetch(url);
      if (!res.ok) throw new Error('API error');
      const data = await res.json();
      
      const newPrices: Record<string, number> = {};
      for (const [symbol, id] of Object.entries(COINS)) {
        if (symbol === 'USDT') {
          newPrices[symbol] = 1;
        } else {
          const price = data[id]?.usd;
          if (price) newPrices[symbol] = price;
        }
      }
      setPrices(newPrices);
      setLastUpdate(new Date().toLocaleTimeString());
      
      if (amount && !isNaN(parseFloat(amount))) {
        convert(parseFloat(amount), from, to, newPrices);
      }
    } catch (e) {
      setError('Не удалось загрузить курсы. Попробуйте позже.');
    } finally {
      setLoading(false);
    }
  };

  const convert = (val: number, fromSym: string, toSym: string, priceMap: Record<string, number>) => {
    if (!priceMap[fromSym] || !priceMap[toSym]) {
      setResult(null);
      return;
    }
    const inUsd = val * priceMap[fromSym];
    const converted = inUsd / priceMap[toSym];
    setResult(converted);
  };

  useEffect(() => {
    if (amount && !isNaN(parseFloat(amount)) && prices[from] && prices[to]) {
      convert(parseFloat(amount), from, to, prices);
    } else {
      setResult(null);
    }
  }, [amount, from, to, prices]);

  useEffect(() => {
    fetchPrices();
    const interval = setInterval(fetchPrices, 60000);
    return () => clearInterval(interval);
  }, []);

  const handleAmountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    if (val === '' || /^\d*\.?\d*$/.test(val)) {
      setAmount(val);
    }
  };

  const handleSwap = () => {
    setFrom(to);
    setTo(from);
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.3, delay: 0.1 }}
      style={glassCardStyle}
      className="mt-4"
    >
      <div className="flex items-center justify-between mb-3">
        <h3 className="text-lg font-semibold text-[var(--tg-theme-text-color)]">🪙 Криптоконвертер</h3>
        <button
          onClick={fetchPrices}
          disabled={loading}
          className="text-[var(--tg-theme-hint-color)] hover:text-[var(--tg-theme-link-color)] transition-colors disabled:opacity-50"
        >
          <RefreshCw size={18} className={loading ? 'animate-spin' : ''} />
        </button>
      </div>

      <div className="flex gap-2 items-center">
        <div className="flex-1">
          <select
            value={from}
            onChange={(e) => setFrom(e.target.value)}
            className="w-full p-3 rounded-xl bg-white/5 border border-white/10 text-[var(--tg-theme-text-color)] focus:border-orange-500 focus:outline-none"
          >
            {Object.keys(COINS).map((sym) => (
              <option key={sym} value={sym}>{CURRENCY_NAMES[sym]}</option>
            ))}
          </select>
          <input
            type="text"
            value={amount}
            onChange={handleAmountChange}
            placeholder="Сумма"
            className="w-full mt-2 p-3 rounded-xl bg-white/5 border border-white/10 text-[var(--tg-theme-text-color)] placeholder:text-[var(--tg-theme-hint-color)] focus:border-orange-500 focus:outline-none"
          />
        </div>

        <button
          onClick={handleSwap}
          className="p-2 rounded-full bg-white/5 hover:bg-white/10 transition-colors self-center"
        >
          <ArrowRight size={24} className="text-[var(--tg-theme-link-color)]" />
        </button>

        <div className="flex-1">
          <select
            value={to}
            onChange={(e) => setTo(e.target.value)}
            className="w-full p-3 rounded-xl bg-white/5 border border-white/10 text-[var(--tg-theme-text-color)] focus:border-orange-500 focus:outline-none"
          >
            {Object.keys(COINS).map((sym) => (
              <option key={sym} value={sym}>{CURRENCY_NAMES[sym]}</option>
            ))}
          </select>
          <div className="w-full mt-2 p-3 rounded-xl bg-white/5 border border-white/10 text-[var(--tg-theme-text-color)] min-h-[48px] flex items-center">
            {result !== null ? (
              <span className="text-orange-500 font-bold text-lg">
                {result.toFixed(8)}
              </span>
            ) : (
              <span className="text-[var(--tg-theme-hint-color)] text-sm">Результат</span>
            )}
          </div>
        </div>
      </div>

      {error && <p className="text-red-400 text-center mt-3 text-sm">{error}</p>}

      {lastUpdate && !error && (
        <p className="text-[var(--tg-theme-hint-color)] text-xs text-center mt-3">
          Обновлено: {lastUpdate}
        </p>
      )}
    </motion.div>
  );
}
