import { useState } from 'react';
import { ArrowLeft, ShoppingBag, ChevronDown, ChevronUp, Lock } from 'lucide-react';
import type { Asset } from '../data/mockAssets';
import { usePremiumCart } from '../context/PremiumCartContext';

interface Props {
  asset: Asset;
  onBack: () => void;
}

export default function AssetDetail({ asset, onBack }: Props) {
  const [showLegal, setShowLegal] = useState(false);
  const [currentImage, setCurrentImage] = useState(0);
  const { addToCart } = usePremiumCart();

  const nextImage = () => {
    if (asset.image_urls.length > 1) {
      setCurrentImage((prev) => (prev + 1) % asset.image_urls.length);
    }
  };

  return (
    <div className="flex flex-col">
      <button onClick={onBack} className="flex items-center gap-2 text-[var(--tg-theme-text-color)] mb-4 shrink-0">
        <ArrowLeft size={20} />
        <span>Назад</span>
      </button>

      <div className="relative rounded-2xl overflow-hidden mb-4 shrink-0" onClick={nextImage}>
        <img
          src={asset.image_urls[currentImage] || ''}
          alt={asset.name}
          className="w-full h-56 object-cover"
        />
        {asset.image_urls.length > 1 && (
          <div className="absolute bottom-2 left-1/2 -translate-x-1/2 flex gap-1">
            {asset.image_urls.map((_, idx) => (
              <div
                key={idx}
                className={`w-2 h-2 rounded-full ${idx === currentImage ? 'bg-brand' : 'bg-white/50'}`}
              />
            ))}
          </div>
        )}
      </div>

      <h2 className="text-xl font-bold text-[var(--tg-theme-text-color)] mb-2 shrink-0">{asset.name}</h2>
      <div className="flex items-center gap-2 mb-3 shrink-0">
        <span className="text-brand text-2xl font-bold">{asset.price}</span>
        {asset.available_units > 0 && (
          <span className="text-[var(--tg-theme-hint-color)] text-sm">• {asset.available_units} доступно</span>
        )}
      </div>

      <p className="text-[var(--tg-theme-text-color)] mb-4">{asset.description}</p>

      <div className="border border-white/10 rounded-xl overflow-hidden mb-4">
        <button
          onClick={() => setShowLegal(!showLegal)}
          className="w-full flex items-center justify-between p-4 text-left text-[var(--tg-theme-text-color)]"
        >
          <span className="flex items-center gap-2">
            <Lock size={16} />
            Юридическая информация
          </span>
          {showLegal ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
        </button>
        {showLegal && (
          <div className="px-4 pb-4 text-[var(--tg-theme-hint-color)] text-sm leading-relaxed">
            {asset.legal_info}
          </div>
        )}
      </div>

      <button
        onClick={() => addToCart(asset)}
        className="w-full bg-brand hover:bg-brand-dark text-white font-semibold py-3 rounded-xl flex items-center justify-center gap-2 transition-colors active:scale-95 shrink-0"
      >
        <ShoppingBag size={20} />
        Добавить в корзину
      </button>
    </div>
  );
}
