import { useState } from 'react';
import { AppRoot } from '@telegram-apps/telegram-ui';
import { AnimatePresence, motion } from 'framer-motion';
import { Package, Diamond } from 'lucide-react';
import { Anchor, Vault } from 'lucide-react';
import ProductList from './components/ProductList';
import CartView from './components/CartView';
import DemurrageCalculator from './components/DemurrageCalculator';
import PremiumApp from './premium/PremiumApp';
import { PremiumCartProvider } from './premium/context/PremiumCartContext';
import SplashScreen from './components/SplashScreen';

type Tab = 'catalog' | 'cart' | 'premium' | 'demurrage';

export default function App() {
  const [activeTab, setActiveTab] = useState<Tab>('catalog');
  const [showSplash, setShowSplash] = useState(true);

  return (
    <>
      {showSplash && <SplashScreen onFinish={() => setShowSplash(false)} />}
      <AppRoot className="pb-20 bg-[var(--tg-theme-bg-color)]">
        {activeTab !== 'premium' && (
          <div className="relative bg-gradient-to-r from-brand to-brand-light px-4 pt-6 pb-8 shadow-lg">
            <h1 className="text-2xl font-bold text-white text-center tracking-wide">
              {activeTab === 'cart' ? 'ATOMICA FIN' : 'ATOMICA DIAMAN'}
            </h1>
            <p className="text-center text-white/80 text-xs mt-1">
              {activeTab === 'cart' ? ' ' : 'Партнерские программы'}
            </p>
          </div>
        )}

        <AnimatePresence mode="wait">
          {activeTab === 'catalog' && (
            <motion.div key="catalog" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="px-4 pt-4">
              <ProductList />
            </motion.div>
          )}
          {activeTab === 'cart' && (
            <motion.div key="cart" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="px-4 pt-4">
              <CartView />
            </motion.div>
          )}
          {activeTab === 'premium' && (
            <motion.div key="premium" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }}>
              <PremiumCartProvider>
                <PremiumApp />
              </PremiumCartProvider>
            </motion.div>
          )}
          {activeTab === 'demurrage' && (
            <motion.div key="demurrage" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} className="px-4 pt-4">
              <DemurrageCalculator />
            </motion.div>
          )}
        </AnimatePresence>

        <nav className="fixed bottom-2 left-4 right-4 h-16 backdrop-blur-xl bg-[color-mix(in_srgb,var(--tg-theme-bg-color)_70%,transparent)] border border-white/10 rounded-2xl flex justify-around items-center z-50 shadow-lg shadow-black/10">
          <button onClick={() => setActiveTab('catalog')} className={`flex flex-col items-center gap-0.5 transition-all duration-200 ${activeTab === 'catalog' ? 'text-brand scale-105' : 'text-[var(--tg-theme-hint-color)]'}`}>
            <Package size={22} strokeWidth={activeTab === 'catalog' ? 2.5 : 2} />
            <span className="text-[10px] font-semibold">DIAMAN</span>
          </button>
          <button onClick={() => setActiveTab('cart')} className={`flex flex-col items-center gap-0.5 transition-all duration-200 relative ${activeTab === 'cart' ? 'text-brand scale-105' : 'text-[var(--tg-theme-hint-color)]'}`}>
            <Vault size={22} strokeWidth={activeTab === 'cart' ? 2.5 : 2} />
            <span className="text-[10px] font-semibold">FinSector</span>
          </button>
          <button onClick={() => setActiveTab('premium')} className={`flex flex-col items-center gap-0.5 transition-all duration-200 ${activeTab === 'premium' ? 'text-brand scale-105' : 'text-[var(--tg-theme-hint-color)]'}`}>
            <Diamond size={22} strokeWidth={activeTab === 'premium' ? 2.5 : 2} />
            <span className="text-[10px] font-semibold">Premium</span>
          </button>
          <button onClick={() => setActiveTab('demurrage')} className={`flex flex-col items-center gap-0.5 transition-all duration-200 ${activeTab === 'demurrage' ? 'text-brand scale-105' : 'text-[var(--tg-theme-hint-color)]'}`}>
            <Anchor size={22} strokeWidth={activeTab === 'demurrage' ? 2.5 : 2} />
            <span className="text-[10px] font-semibold">Freight</span>
          </button>
        </nav>
      </AppRoot>
    </>
  );
}
