import { useState } from 'react';
import { motion } from 'framer-motion';
import { Diamond, Handshake, Factory } from 'lucide-react';

const glassCardStyle: React.CSSProperties = {
  background: 'var(--tg-theme-secondary-bg-color)',
  borderRadius: '24px',
  border: '1px solid rgba(255, 117, 25, 0.25)',
  boxShadow: '0 8px 32px rgba(0, 0, 0, 0.2)',
  padding: '20px',
  cursor: 'pointer',
};

const iconContainerStyle: React.CSSProperties = {
  width: '56px',
  height: '56px',
  borderRadius: '16px',
  background: 'linear-gradient(135deg, rgba(255, 117, 25, 0.15), rgba(255, 117, 25, 0.05))',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  marginBottom: '12px',
};

const blocks = [
  {
    title: 'Дистрибьюция Premium-брендов',
    description: 'Договора на дистрибьюцию для стран и регионов',
    icon: <Handshake size={28} color="var(--tg-theme-link-color)" />,
  },
  {
    title: 'Производственное оборудование',
    description: 'Оборудование для организации сопутствующих/высокорентабельных производственных процессов',
    icon: <Factory size={28} color="var(--tg-theme-link-color)" />,
  },
  {
    title: 'Ликвидные активы',
    description: 'Ликвидные активы с ультрамаржинальностью',
    icon: <Diamond size={28} color="var(--tg-theme-link-color)" />,
  },
];

export default function ProductList() {
  const [selected, setSelected] = useState<number | null>(null);

  return (
    <div className="px-4 pt-4 pb-24">
      <h2 className="text-xl font-semibold text-[var(--tg-theme-text-color)] mb-4">
        Возможности клуба
      </h2>
      <div className="flex flex-col gap-4">
        {blocks.map((block, i) => (
          <motion.div
            key={i}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: i * 0.1, duration: 0.4 }}
            style={glassCardStyle}
            onClick={() => setSelected(i)}
          >
            <div style={iconContainerStyle}>{block.icon}</div>
            <h3 className="text-lg font-semibold text-[var(--tg-theme-text-color)]">
              {block.title}
            </h3>
            <p className="text-sm text-[var(--tg-theme-hint-color)] mt-1">
              {block.description}
            </p>
          </motion.div>
        ))}
      </div>

      {selected !== null && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-[200] bg-black/60 flex items-center justify-center p-4"
          onClick={() => setSelected(null)}
        >
          <motion.div
            initial={{ scale: 0.9 }}
            animate={{ scale: 1 }}
            exit={{ scale: 0.9 }}
            style={glassCardStyle}
            onClick={(e) => e.stopPropagation()}
            className="text-center max-w-sm"
          >
            <div className="text-5xl mb-4">🔒</div>
            <h3 className="text-xl font-bold text-[var(--tg-theme-text-color)] mb-2">
              {blocks[selected].title}
            </h3>
            <p className="text-[var(--tg-theme-link-color)] font-semibold text-lg">
              Доступ по приглашению участников клуба
            </p>
            <p className="text-[var(--tg-theme-hint-color)] text-sm mt-2">
              Для получения информации обратитесь к вашему персональному менеджеру.
            </p>
            <button
              onClick={() => setSelected(null)}
              style={{
                marginTop: '16px',
                padding: '10px 24px',
                background: 'linear-gradient(135deg, var(--tg-theme-link-color), #e55a00)',
                color: 'white',
                border: 'none',
                borderRadius: '12px',
                fontWeight: 600,
              }}
            >
              Закрыть
            </button>
          </motion.div>
        </motion.div>
      )}
    </div>
  );
}
