import { useState } from 'react';
import { motion } from 'framer-motion';
import { ShoppingCart, Minus, Plus, Trash2 } from 'lucide-react';
import { usePremiumCart } from '../context/PremiumCartContext';
import OrderForm from './OrderForm';

interface Props {
  onBack: () => void;
}

export default function CartView({ onBack }: Props) {
  const { items, removeFromCart, updateQuantity, total } = usePremiumCart();
  const [showForm, setShowForm] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  if (submitted) {
    return (
      <motion.div initial={{ scale: 0.8 }} animate={{ scale: 1 }} className="flex flex-col items-center mt-20">
        <div className="w-20 h-20 rounded-full bg-gold/20 flex items-center justify-center mb-4">
          <ShoppingCart className="text-gold" size={36} />
        </div>
        <h2 className="text-xl font-bold text-white mb-2">Заявка отправлена</h2>
        <p className="text-white/50 text-center">Менеджер свяжется с вами</p>
        <button onClick={() => { setSubmitted(false); onBack(); }} className="mt-6 text-gold font-medium">
          Вернуться в каталог
        </button>
      </motion.div>
    );
  }

  if (items.length === 0) {
    return (
      <div className="flex flex-col items-center mt-20 text-white/50">
        <ShoppingCart size={48} className="mb-3 opacity-40" />
        <p>Корзина пуста</p>
      </div>
    );
  }

  return (
    <div>
      <h2 className="text-xl font-bold text-white mb-4">Корзина</h2>
      <div className="space-y-3">
        {items.map((item: { asset: { id: string; name: string; price: string }; quantity: number }) => (
          <motion.div
            key={item.asset.id}
            layout
            className="bg-card rounded-xl p-3 flex items-center gap-3 border border-white/5"
          >
            <div className="flex-1 min-w-0">
              <h3 className="text-white font-medium truncate">{item.asset.name}</h3>
              <div className="text-gold text-sm">{item.asset.price}</div>
            </div>
            <div className="flex items-center gap-2">
              <button onClick={() => updateQuantity(item.asset.id, -1)} className="w-6 h-6 rounded-full bg-white/10 flex items-center justify-center text-white">
                <Minus size={14} />
              </button>
              <span className="text-white w-6 text-center">{item.quantity}</span>
              <button onClick={() => updateQuantity(item.asset.id, 1)} className="w-6 h-6 rounded-full bg-white/10 flex items-center justify-center text-white">
                <Plus size={14} />
              </button>
            </div>
            <button onClick={() => removeFromCart(item.asset.id)} className="text-red-400">
              <Trash2 size={18} />
            </button>
          </motion.div>
        ))}
      </div>

      <div className="border-t border-white/10 pt-4 mt-4 flex justify-between">
        <span className="text-lg text-white">Итого</span>
        <span className="text-xl font-bold text-gold">€{total.toFixed(2)}</span>
      </div>

      <button
        onClick={() => setShowForm(true)}
        className="w-full bg-gold hover:bg-gold-light text-dark font-semibold py-3 rounded-xl mt-6 transition-colors active:scale-95"
      >
        Оставить заявку
      </button>

      {showForm && (
        <OrderForm
          onClose={() => setShowForm(false)}
          onSubmit={() => { setShowForm(false); setSubmitted(true); }}
        />
      )}
    </div>
  );
}
