import { createContext, useContext, useState, ReactNode } from 'react';
import type { Asset } from '../data/mockAssets';

interface CartItem {
  asset: Asset;
  quantity: number;
}

interface PremiumCartContextType {
  items: CartItem[];
  addToCart: (asset: Asset) => void;
  removeFromCart: (id: string) => void;
  updateQuantity: (id: string, delta: number) => void;
  total: number;
}

const PremiumCartContext = createContext<PremiumCartContextType>({} as PremiumCartContextType);

export function PremiumCartProvider({ children }: { children: ReactNode }) {
  const [items, setItems] = useState<CartItem[]>([]);

  const addToCart = (asset: Asset) => {
    setItems(prev => {
      const existing = prev.find(item => item.asset.id === asset.id);
      if (existing) {
        return prev.map(item =>
          item.asset.id === asset.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { asset, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setItems(prev => prev.filter(item => item.asset.id !== id));
  };

  const updateQuantity = (id: string, delta: number) => {
    setItems(prev =>
      prev
        .map(item =>
          item.asset.id === id ? { ...item, quantity: Math.max(0, item.quantity + delta) } : item
        )
        .filter(item => item.quantity > 0)
    );
  };

  const total = items.reduce((sum, item) => {
    if (item.asset.price === 'Price on request') return sum;
    const price = parseFloat(item.asset.price.replace(/[^0-9.]/g, ''));
    return sum + (isNaN(price) ? 0 : price * item.quantity);
  }, 0);

  return (
    <PremiumCartContext.Provider value={{ items, addToCart, removeFromCart, updateQuantity, total }}>
      {children}
    </PremiumCartContext.Provider>
  );
}

export const usePremiumCart = () => useContext(PremiumCartContext);
