import { useEffect, useState } from 'react';
import logo from '../assets/logo.png';

interface Props {
  onFinish: () => void;
}

export default function SplashScreen({ onFinish }: Props) {
  const [fadeOut, setFadeOut] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => {
      setFadeOut(true);
      setTimeout(onFinish, 500);
    }, 5000); // 3 секунды, можно увеличить

    return () => clearTimeout(timer);
  }, [onFinish]);

  return (
    <div
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        width: '100vw',
        height: '100vh',
        backgroundColor: '#000000',
        zIndex: 9999,
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        opacity: fadeOut ? 0 : 1,
        transition: 'opacity 0.5s ease',
      }}
    >
      <img
        src={logo}
        alt="ATOMICA"
        style={{
          maxWidth: '70%',
          maxHeight: '70%',
          objectFit: 'contain',
          animation: 'pulse 2s ease-in-out infinite',
        }}
      />
      <style>{`
        @keyframes pulse {
          0% { transform: scale(0.95); opacity: 0.8; filter: brightness(1); }
          50% { transform: scale(1.05); opacity: 1; filter: brightness(1.2); }
          100% { transform: scale(0.95); opacity: 0.8; filter: brightness(1); }
        }
      `}</style>
    </div>
  );
}
